"""Targeted definitions/comparison, not certification of all 43 antifaction units."""
import json
from pathlib import Path
P='https://www.planalto.gov.br/ccivil_03/'
units={
'art-1':dict(simples='A Lei 15.358/2026 trata de organizações criminosas ultraviolentas, grupos paramilitares e milícias que atentem por violência/grave ameaça contra paz, coletividade ou instituições. Cria domínio social estruturado e favorecimento, além de alterar vários diplomas. Não substitui automaticamente os crimes associativos anteriores nem transforma todo concurso de pessoas em facção.',pontos=['Identifique conduta, vínculo e contexto; não apenas o nome popular do grupo.'],atencao=['É lei de 2026: examinar tempo do fato e proibição de retroatividade mais gravosa. Dispositivos são objeto de controle constitucional nas ADIs 7952, 7956, 7957 e 7958; consultar andamento e decisões pertinentes antes de afirmar tese consolidada. Este lote não certifica todos os dispositivos ou resultados dessas ações.'],exemplo='Três pessoas mantêm grupo estável para fraudes sem os elementos de domínio/ultraviolência do regime novo: o número, sozinho, não o converte em facção. Variação: emprego de grave ameaça para impor controle territorial exige exame da definição e da conduta específica do art. 2º.',prova=['Toda associação de três pessoas é automaticamente facção da lei nova? Não; o número não dispensa os elementos materiais da definição e da conduta.'],termos=[],remissoes=[P+'decreto-lei/del2848compilado.htm','https://portal.stf.jus.br/processos/detalhe.asp?incidente=7576278']),
'art-2':dict(simples='Domínio social estruturado exige integrante do agrupamento definido e uma das condutas dos incisos I–X. Pena literal: 20 a 40 anos, sem prejuízo das sanções indicadas. O §2º define facção como agrupamento de três ou mais com os elementos de violência/grave ameaça/coação e controle, intimidação, ataque a serviços ou atos destinados aos crimes desta lei. Isso não se confunde com associação criminosa, associação para tráfico ou organização da Lei 12.850.',pontos=['Memória: TRÁFICO começa em 2; ASSOCIAÇÃO e FACÇÃO em 3; ORGANIZAÇÃO geral em 4. O número é só a primeira pergunta, nunca a resposta completa.','CP 288: três ou mais, finalidade específica de crimes e vínculo estável/permanente; pena básica 1–3 anos. §1º majorante e §2º sobre solicitar/contratar crime, incluído em 2025, exigem leitura própria.','Drogas 35: duas ou mais, finalidade dos arts. 33 caput/§1º e 34; vínculo estável/permanente segundo STJ mesmo com a expressão reiteradamente ou não. Pena 3–10 e 700–1.200 dias-multa. Não presumir associação por presença em território de facção.','Lei 12.850 art. 1º §1º: quatro ou mais, estrutura ordenada e divisão de tarefas, ainda que informal, vantagem de qualquer natureza mediante infrações com pena máxima superior a quatro anos OU caráter transnacional.','Facção da Lei 15.358: três ou mais e elementos ultraviolentos da definição. A participação e a conduta concreta precisam ser demonstradas; não usar o mínimo de quatro do conceito geral automaticamente.'],atencao=['A comparação não determina cumulação automática de crimes pelo mesmo fato: examinar elementos, especialidade/concurso e evitar dupla valoração. Não confundir definições associativas com concurso eventual para um delito isolado.','O artigo possui outros parágrafos sobre majorantes, preparatórios, benefícios, custódia e competência; sua literalidade não certifica constitucionalidade ou prisão automática. O §9º deve ser confrontado com Constituição, decisão judicial fundamentada e regime cautelar do CPP. As ADIs indicadas precisam ser acompanhadas; este aprofundamento se limita às definições e comparação, não resolve todo o controle judicial.'],exemplo='Dois agentes mantêm vínculo estável e permanente para os crimes de drogas especificados: examina-se art. 35, mesmo sem atingir três. Três associados estáveis para crimes patrimoniais, sem elementos de ultraviolência/domínio da lei nova: examina-se CP 288. Variação: quatro pessoas com estrutura, tarefas e finalidade que satisfaçam a Lei 12.850 podem formar organização geral. Já três pessoas que imponham controle territorial por grave ameaça exigem exame da definição de facção e da conduta do art. 2º; a contagem isolada não basta. Duas pessoas reunidas ocasionalmente para um delito não preenchem automaticamente o vínculo estável do art. 35.',prova=['Duas pessoas com vínculo estável para os crimes de drogas indicados podem preencher art. 35? Sim; o mínimo é dois, com os demais elementos.','Três pessoas são suficientes por si para provar facção? Não; precisam dos elementos materiais da definição e da conduta examinada.','O mínimo da organização geral da Lei 12.850 é quatro? Sim; juntamente com estrutura, tarefas e finalidade legal.','A expressão reiteradamente ou não do art. 35 dispensa vínculo estável segundo STJ? Não; a jurisprudência exige estabilidade e permanência.'],termos=[],remissoes=[P+'decreto-lei/del2848compilado.htm',P+'_ato2004-2006/2006/lei/l11343.htm',P+'_ato2011-2014/2013/lei/l12850.htm','https://www.stj.jus.br/sites/portalp/Paginas/Comunicacao/Noticias/26082022-Falta-de-demonstracao-de-vinculo-permanente-afasta-condenacao-por-associacao-para-o-trafico.aspx','https://scon.stj.jus.br/SCON/GetInteiroTeorDoAcordao?dt_publicacao=22%2F04%2F2026&num_registro=202504764515','https://portal.stf.jus.br/processos/detalhe.asp?incidente=7576278'])
}
Path('scripts/explicacoes/antifaccao-comparacao-revisao-aplicada-2026-10-11.json').write_text(json.dumps(dict(course_slug='antifaccao',units=units),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(units),'explicitly authored definitions and comparisons')
